    int n, m, p;
    if (scanf("%d %d %d", &n, &m, &p) != 3) {
        return 0;
    }

    int *R = (int *)malloc((n + 1) * sizeof(int));
    int *C = (int *)malloc((m + 1) * sizeof(int));

    if (!R || !C) {
        return 0;
    }

    for (int i = 1; i <= n; i++) {
        R[i] = i;
    }
    for (int j = 1; j <= m; j++) {
        C[j] = j;
    }

    for (int k = 0; k < p; k++) {
        char op;
        int a, b;
        scanf(" %c %d %d", &op, &a, &b);
        if (op == 'L') {
            int tmp = R[a];
            R[a] = R[b];
            R[b] = tmp;
        } else if (op == 'C') {
            int tmp = C[a];
            C[a] = C[b];
            C[b] = tmp;
        }
    }

    for (int i = 1; i <= n; i++) {
        long long base = (long long)(R[i] - 1) * m;
        for (int j = 1; j <= m; j++) {
            long long student = base + C[j];
            if (j > 1) {
                putchar(' ');
            }
            printf("%lld", student);
        }
        putchar('\n');
    }

    free(R);
    free(C);

    return 0;
}
